const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;background:transparent;color:var(--ink);font:12px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.cal{display:flex;flex-direction:column;gap:6px;width:100%;height:100%;min-width:0;min-height:0;padding:8px;background:var(--paper);border-radius:16px;overflow:hidden}\n.card button{font:inherit;color:inherit;cursor:pointer;margin:0}\n.card button:focus-visible,.card input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}\n\n.top{display:grid;gap:6px;align-items:center;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"nav add\" \"tabs tabs\"}\n.ttl{grid-area:ttl;display:none;min-width:0}\n.ttl strong{font-size:14px}\n.sum{font-size:11px;color:var(--muted)}\n.nav{grid-area:nav;display:flex;align-items:center;gap:2px;min-width:0}\n.nav-t{font-weight:700;font-size:12px;padding-left:2px}\n.nb{flex:none;width:22px;height:26px;padding:0;border:1px solid var(--line);border-radius:7px;background:var(--panel-paper);color:var(--ink);font-size:14px;line-height:1}\n.wk-l{flex:1;min-width:0;height:26px;padding:0 2px;border:0;background:transparent;color:var(--ink);font-size:12px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tabs{grid-area:tabs;display:flex;gap:2px;padding:2px;background:var(--soft);border-radius:999px;min-width:0}\n.tab{flex:1;min-width:0;height:22px;padding:0 2px;border:0;border-radius:999px;background:transparent;color:var(--ink);font-size:11px;white-space:nowrap}\n.tab b{margin-left:3px;font-weight:600}\n.tab[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);font-weight:700}\n.add{grid-area:add;height:28px;min-width:28px;padding:0 8px;border:0;border-radius:999px;background:var(--accent);color:var(--on-accent);font-weight:700;white-space:nowrap}\n.add-t{display:none}\n\n.msg{flex:none;padding:3px 7px;border:1px solid var(--accent-alt);border-radius:7px;background:var(--soft);color:var(--ink);font-size:11px}\n\n.strip{flex:none;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px}\n.day{display:flex;flex-direction:column;align-items:center;min-width:0;padding:3px 0;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);line-height:1.15}\n.dw{font-size:10px;color:var(--muted)}\n.dd{font-size:13px;font-weight:700}\n.dc{font-size:10px;min-height:11px}\n.day.today{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}\n.day.sel{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.day.sel .dw{color:var(--on-accent)}\n\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px;padding-right:2px;overscroll-behavior:contain}\n.grp{display:flex;flex-direction:column;gap:5px;min-width:0}\n.gh{margin:0;display:flex;align-items:baseline;gap:6px;font-size:11px;font-weight:700;color:var(--muted)}\n.gn{font-weight:400}\n.grp.today .gh{color:var(--accent)}\n.grp.late .gh{color:var(--ink)}\n\n.post{display:flex;flex-direction:column;gap:5px;min-width:0;padding:6px 7px;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px}\n.post.is-pub{border-style:dashed}\n.post.is-late{border-color:var(--accent-alt)}\n.p-top{display:flex;gap:4px;align-items:flex-start;min-width:0}\n.p-title{flex:1;min-width:0;font-size:13px;font-weight:700;line-height:1.3;overflow-wrap:anywhere}\n.is-pub .p-title{color:var(--muted)}\n.ico{flex:none;width:26px;height:26px;padding:0;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--ink)}\n.p-meta{display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:11px;min-width:0}\n.plat{max-width:100%;padding:1px 6px;border-radius:999px;background:var(--soft);color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dtw{position:relative;display:inline-flex;align-items:center;padding:1px 6px;border:1px solid var(--line);border-radius:999px;background:var(--paper);color:var(--ink);white-space:nowrap}\n.dtw input{position:absolute;inset:0;width:100%;height:100%;padding:0;border:0;opacity:0;cursor:pointer}\n.dtw input::-webkit-calendar-picker-indicator{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}\n.dtw:focus-within{outline:2px solid var(--accent)}\n.tag{padding:1px 6px;border-radius:999px;font-weight:700;white-space:nowrap}\n.tag.late{border:1px solid var(--accent-alt);background:var(--soft);color:var(--ink)}\n.tag.pub{background:var(--accent);color:var(--on-accent)}\n\n\n.p-checks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:3px}\n.chip{display:flex;align-items:center;justify-content:center;gap:1px;min-width:0;height:26px;padding:0 2px;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--ink);font-size:11px;white-space:nowrap}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:700}\n.ck{display:inline-block;width:10px;text-align:center}\n.p-ft{display:flex;align-items:center;gap:6px;min-width:0}\n.bar{flex:1;min-width:20px;height:5px;border-radius:3px;background:var(--soft);overflow:hidden}\n.bar i{display:block;height:100%;width:0;background:var(--accent)}\n.bar[data-n=\"1\"] i{width:25%}\n.bar[data-n=\"2\"] i{width:50%}\n.bar[data-n=\"3\"] i{width:75%}\n.bar[data-n=\"4\"] i{width:100%}\n.cnt{flex:none;min-width:22px;font-size:11px;color:var(--muted)}\n.pubbtn{flex:none;height:24px;padding:0 8px;border:1px solid var(--accent);border-radius:7px;background:transparent;color:var(--ink);font-size:11px;white-space:nowrap}\n.pubbtn.go{background:var(--accent);color:var(--on-accent);font-weight:700}\n\n.empty{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:8px;text-align:center;color:var(--muted);font-size:12px}\n\n.form{display:flex;flex-direction:column;gap:8px;height:100%;min-height:0;min-width:0}\n.f-hd{flex:none;font-size:14px;font-weight:700}\n.f-body{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fld>span{font-size:11px;color:var(--muted)}\n.in{width:100%;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px}\n.pcs{display:flex;flex-wrap:wrap;gap:4px}\n.pc{height:24px;padding:0 8px;border:1px solid var(--line);border-radius:999px;background:var(--soft);color:var(--ink);font-size:11px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.f-ft{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:6px}\n.btn{height:30px;padding:0 12px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font-size:12px;white-space:nowrap}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:700}\n.btn.quiet{margin-left:auto;background:transparent}\n.btn.warn{background:var(--soft);border-color:var(--accent-alt);font-weight:700}\n.ask{flex:1 0 100%;font-size:12px;font-weight:700}\n\n.card[data-size=\"3x3\"] .cal,.card[data-size=\"3x6\"] .cal{padding:7px}\n.card[data-size=\"3x3\"] .post,.card[data-size=\"3x6\"] .post{padding:5px 6px}\n\n.card[data-size=\"6x3\"] .top{grid-template-columns:auto minmax(0,1fr) auto;grid-template-areas:\"nav tabs add\"}\n.card[data-size=\"6x3\"] .tabs{max-width:190px;justify-self:start}\n.card[data-size=\"6x3\"] .add-t,.card[data-size=\"6x6\"] .add-t{display:inline}\n.card[data-size=\"6x3\"] .nav{width:140px}\n.card[data-size=\"6x3\"] .grp,.card[data-size=\"6x6\"] .grp{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;align-items:start}\n.card[data-size=\"6x3\"] .gh,.card[data-size=\"6x6\"] .gh{grid-column:1/-1}\n\n.card[data-size=\"6x6\"] .cal{padding:12px;gap:8px}\n.card[data-size=\"6x6\"] .top{grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"ttl add\" \"nav tabs\";row-gap:8px}\n.card[data-size=\"6x6\"] .ttl{display:block}\n.card[data-size=\"6x6\"] .nav{width:150px}\n.card[data-size=\"6x6\"] .tabs{justify-self:end;width:190px}\n.card[data-size=\"6x6\"] .list{gap:10px}\n.card[data-size=\"6x6\"] .post{padding:8px 9px;gap:6px}\n.card[data-size=\"6x6\"] .dd{font-size:15px}\n.card[data-size=\"6x6\"] .day{padding:5px 0}\n";
const CHECKS=[{k:'copy',t:'文案'},{k:'img',t:'配图'},{k:'cover',t:'封面'},{k:'proof',t:'校对'}];
const WD=['周一','周二','周三','周四','周五','周六','周日'];
const WS=['一','二','三','四','五','六','日'];
function p2(n){return (n<10?'0':'')+n;}
function dn(s){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');if(!m)return NaN;return Math.floor(Date.UTC(+m[1],+m[2]-1,+m[3])/86400000);}
function ds(n){const d=new Date(n*86400000);return d.getUTCFullYear()+'-'+p2(d.getUTCMonth()+1)+'-'+p2(d.getUTCDate());}
function okDate(s){const n=dn(s);return !isNaN(n)&&ds(n)===s;}
function mon(n){return n-((n+3)%7);}
function md(s){return s.slice(5,7)+'/'+s.slice(8,10);}
function wdOf(s){return WD[(dn(s)+3)%7];}
function posts(s){return s&&Array.isArray(s.posts)?s.posts:[];}
function doneN(p){const c=p.checks||{};let n=0;CHECKS.forEach(function(x){if(c[x.k])n++;});return n;}
function byDate(a,b){return a.date<b.date?-1:a.date>b.date?1:(a.createdAt||0)-(b.createdAt||0);}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const sz=ctx.size||root.getAttribute('data-size')||'3x3';
  const stripOn=sz==='3x6'||sz==='6x6';
  const today=day(), tn=dn(today);
  if(!ui.view)ui.view='week';
  if(typeof ui.wk!=='number')ui.wk=0;
  const all=posts(state).slice().sort(byDate);
  const ws=mon(tn)+ui.wk*7, we=ws+6;
  const sel=(ui.view==='week'&&stripOn&&ui.selDay&&dn(ui.selDay)>=ws&&dn(ui.selDay)<=we)?ui.selDay:null;
  const wk=all.filter(function(p){const n=dn(p.date);return n>=ws&&n<=we;});

  function h(tag,attrs,...kids){
    const out=[];
    (function add(k){
      if(Array.isArray(k))k.forEach(add);
      else if(k!==null&&k!==undefined&&k!==false&&k!=='')out.push(typeof k==='number'?String(k):k);
    })(kids);
    return el(tag,attrs||{},...out);
  }
  function dayLabel(s){
    return (s.slice(0,4)!==today.slice(0,4)?s.slice(0,4)+'/':'')+md(s)+' '+wdOf(s)+(s===today?' · 今天':'');
  }
  function go(fn){ui.note='';ui.err='';fn();redraw();}
  function fail(msg){ui.note='';ui.err=msg||'保存失败，已保留原内容，请重试';redraw();}
  function run(fn){ui.err='';return update(fn).catch(function(){fail();});}
  function patch(id,fn){
    return run(function(s){
      return Object.assign({},s,{posts:posts(s).map(function(p){return p.id===id?fn(p):p;})});
    });
  }
  function toggle(id,k){
    ui.note='';
    patch(id,function(p){
      const c=Object.assign({},p.checks||{});
      c[k]=!c[k];
      return Object.assign({},p,{checks:c});
    });
  }
  function setDate(id,v){
    if(!okDate(v)){redraw();return;}
    const n=dn(v);
    ui.note=(ui.view==='week'&&(n<ws||n>we))?'已改到 '+md(v)+' '+wdOf(v)+'，不在当前这周，可翻周或到「待发」查看':'';
    patch(id,function(p){return Object.assign({},p,{date:v});});
  }
  function togglePub(id){
    ui.note='';
    patch(id,function(p){
      return p.published
        ?Object.assign({},p,{published:false,publishedAt:''})
        :Object.assign({},p,{published:true,publishedAt:today});
    });
  }
  function defDate(){return sel?sel:(ui.view==='week'&&ui.wk!==0?ds(ws):today);}
  function openForm(p){
    ui.note='';ui.err='';ui.formErr='';ui.delAsk=false;ui.saving=false;
    ui.draft=p?{id:p.id,title:p.title,platform:p.platform||'',date:p.date}:{title:'',platform:'',date:defDate()};
    ui.mode='form';
    redraw();
  }
  function closeForm(){ui.mode=null;ui.draft=null;ui.formErr='';ui.delAsk=false;redraw();}
  function submit(){
    if(ui.saving)return;
    const d=ui.draft, t=(d.title||'').trim(), pf=(d.platform||'').trim();
    if(!t){ui.formErr='请填写标题';redraw();return;}
    if(!okDate(d.date)){ui.formErr='请选择计划发布日';redraw();return;}
    const isNew=!d.id, id=d.id||uid(), created=Date.now(), date=d.date;
    const next=Object.assign({},ui,{mode:null,draft:null,formErr:'',delAsk:false,saving:false,note:'',err:''});
    if(isNew){next.view='week';next.wk=(mon(dn(date))-mon(tn))/7;next.selDay=null;}
    ui.formErr='';ui.saving=true;
    commit(function(s){
      const list=posts(s);
      if(isNew){
        return Object.assign({},s,{posts:list.concat([{id:id,title:t,platform:pf,date:date,
          checks:{copy:false,img:false,cover:false,proof:false},published:false,publishedAt:'',createdAt:created}])});
      }
      return Object.assign({},s,{posts:list.map(function(p){
        return p.id===id?Object.assign({},p,{title:t,platform:pf,date:date}):p;
      })});
    },next).catch(function(){ui.saving=false;ui.formErr='保存失败，内容还在表单里，请重试';redraw();});
  }
  function del(id){
    if(ui.saving)return;
    if(!ui.delAsk){ui.delAsk=true;redraw();return;}
    ui.saving=true;
    commit(function(s){
      return Object.assign({},s,{posts:posts(s).filter(function(p){return p.id!==id;})});
    },Object.assign({},ui,{mode:null,draft:null,formErr:'',delAsk:false,saving:false})).catch(function(){
      ui.saving=false;ui.formErr='删除失败，已保留原内容，请重试';redraw();
    });
  }
  function platformList(){
    const out=[];
    all.forEach(function(p){const n=(p.platform||'').trim();if(n&&out.indexOf(n)<0)out.push(n);});
    return out.slice(0,8);
  }


  function formView(){
    const d=ui.draft, isEdit=!!d.id, pl=platformList();
    const onEnter=function(e){if(e.key==='Enter'){e.preventDefault();submit();}};
    const tIn=h('input',{type:'text',class:'in',value:d.title,maxlength:'80',placeholder:'图文标题','aria-label':'标题',
      oninput:function(e){d.title=e.target.value;},onkeydown:onEnter});
    const pIn=h('input',{type:'text',class:'in',value:d.platform,maxlength:'30',placeholder:'发布平台','aria-label':'平台',
      oninput:function(e){d.platform=e.target.value;},onkeydown:onEnter});
    const dIn=h('input',{type:'date',class:'in',value:d.date,'aria-label':'计划发布日',
      oninput:function(e){d.date=e.target.value;},onchange:function(e){d.date=e.target.value;}});
    const foot=ui.delAsk
      ?[h('span',{class:'ask'},'确认删除这篇？删除后无法恢复。'),
        h('button',{type:'button',class:'btn warn',disabled:!!ui.saving,onclick:function(){del(d.id);}},'确认删除'),
        h('button',{type:'button',class:'btn',onclick:function(){ui.delAsk=false;redraw();}},'返回')]
      :[h('button',{type:'button',class:'btn primary',onclick:submit},isEdit?'保存修改':'保存'),
        h('button',{type:'button',class:'btn',onclick:closeForm},'取消'),
        isEdit?h('button',{type:'button',class:'btn quiet',onclick:function(){del(d.id);}},'删除'):null];
    return h('div',{class:'form'},
      h('div',{class:'f-hd'},isEdit?'编辑图文':'新建图文'),
      h('div',{class:'f-body'},
        h('div',{class:'fld'},h('span',{},'标题'),tIn),
        h('div',{class:'fld'},h('span',{},'平台'),pIn,
          pl.length?h('div',{class:'pcs'},pl.map(function(n){
            return h('button',{type:'button',class:'pc',onclick:function(){d.platform=n;redraw();}},n);
          })):null),
        h('div',{class:'fld'},h('span',{},'计划发布日'),dIn),
        ui.formErr?h('div',{class:'msg',role:'alert'},'⚠ '+ui.formErr):null),
      h('div',{class:'f-ft'},foot));
  }

  function postCard(p){
    const n=doneN(p), late=!p.published&&p.date<today, c=p.checks||{};
    return h('article',{class:'post'+(p.published?' is-pub':'')+(late?' is-late':'')},
      h('div',{class:'p-top'},
        h('div',{class:'p-title'},p.title),
        h('button',{type:'button',class:'ico',title:'编辑标题、平台','aria-label':'编辑：'+p.title,
          onclick:function(){openForm(p);}},'✎')),
      h('div',{class:'p-meta'},
        h('span',{class:'plat'},p.platform||'未填平台'),
        h('span',{class:'dtw',title:'点击改计划发布日'},
          h('span',{},md(p.date)+' '+wdOf(p.date)+' ▾'),
          h('input',{type:'date',value:p.date,'aria-label':'计划发布日：'+p.title,
            onchange:function(e){setDate(p.id,e.target.value);}})),
        late?h('span',{class:'tag late'},'⚠ 逾期'):null,
        p.published?h('span',{class:'tag pub'},'✓ 已发 '+md(p.publishedAt||p.date)):null),
      h('div',{class:'p-checks',role:'group','aria-label':'制作进度'},CHECKS.map(function(x){
        const on=!!c[x.k];
        return h('button',{type:'button',class:'chip'+(on?' on':''),role:'checkbox','aria-checked':on?'true':'false',
          'aria-label':x.t+(on?'，已完成':'，未完成'),onclick:function(){toggle(p.id,x.k);}},
          h('span',{class:'ck','aria-hidden':'true'},on?'✓':'○'),x.t);
      })),
      h('div',{class:'p-ft'},
        h('div',{class:'bar','data-n':String(n)},h('i',{})),
        h('span',{class:'cnt'},n+'/4'),
        h('button',{type:'button',class:'pubbtn'+(!p.published&&n===4?' go':''),onclick:function(){togglePub(p.id);}},
          p.published?'撤销发布':'标记已发布')));
  }


  function runs(list,key,label){
    const out=[];
    list.forEach(function(p){
      const k=key(p);
      let g=out[out.length-1];
      if(!g||g.key!==k){g={key:k,label:label(k),posts:[]};out.push(g);}
      g.posts.push(p);
    });
    return out;
  }
  function groupsOf(){
    if(ui.view==='week'){
      if(sel)return runs(wk.filter(function(p){return p.date===sel;}),function(p){return p.date;},dayLabel);
      const out=[];
      if(ui.wk===0){
        const od=all.filter(function(p){return !p.published&&p.date<ds(ws);});
        if(od.length)out.push({key:'late',label:'⚠ 逾期未发',late:true,posts:od});
      }
      return out.concat(runs(wk,function(p){return p.date;},dayLabel));
    }
    if(ui.view==='todo'){
      const todo=all.filter(function(p){return !p.published;});
      const od=todo.filter(function(p){return p.date<today;});
      const rest=todo.filter(function(p){return p.date>=today;});
      const out=[];
      if(od.length)out.push({key:'late',label:'⚠ 逾期未发',late:true,posts:od});
      return out.concat(runs(rest,function(p){return p.date;},dayLabel));
    }
    const done=all.filter(function(p){return p.published;}).sort(function(a,b){
      const x=a.publishedAt||a.date, y=b.publishedAt||b.date;
      return x<y?1:x>y?-1:0;
    });
    return runs(done,function(p){return p.publishedAt||p.date;},function(k){return '发布于 '+dayLabel(k);});
  }

  function emptyView(){
    let msg, hint=null;
    if(!all.length){msg='还没有图文排期';hint='点「新建」，填标题、平台和计划发布日';}
